import{board}from'./board.js';import{apply,production,invariant}from'./engine.js';import{lessonState,lessonRecruit,prepareFrame,lessonFrame}from'./learn-state.js';
export function onboarding(cards,onFinish){const dialog=document.getElementById('learn'),copy=document.getElementById('lessonCopy'),stage=document.getElementById('lessonScene');let s,step=0,view,preview=false;const headings=['Nobody owns the whole machine.','Start with a useful institution.','Change the conversation.','Now they need each other.','Your next move is yours.'];
 const descriptions=['But someone always controls the next door. Build a small network, make its institutions depend on each other, and bank more points than your rival over eight turns.','The Compute Chokepoint supplies RESOURCES, but needs RULES. Take it for 1 Favor. On its own it earns 1 point after your turn.','You hold MOVE THE FRAME. Use it to turn the A die from 3 to 4. RULES becomes the highest corner: its institutions are now free to recruit.','Your Compute Chokepoint supplies the Peer Review Gate. The Gate supplies the rules the Chokepoint needs. Both needs are met: 2 institutions + 2 × 2 connections = 6 points per turn.','You have two of your three network slots. Fill the last, steal an exposed rival, or use your Plot. Each turn takes one action; then your network earns points. Highest total after eight turns wins.'];
 function btn(text,fn,cls='primary'){const b=document.createElement('button');b.textContent=text;b.className=cls;b.onclick=fn;return b;}
 function draw(){copy.replaceChildren();let n=document.createElement('div');n.className='lesson-number';n.textContent=`${step+1} / 5 · YOUR FIRST TWO TURNS`;let h=document.createElement('h2');h.id='lessonTitle';h.textContent=headings[step];let p=document.createElement('p');p.textContent=descriptions[step];copy.append(n,h,p);document.getElementById('lessonDots').innerHTML=headings.map((_,i)=>`<span class="${i<=step?'lit':''}"></span>`).join('');
 const state=preview?apply(s,lessonFrame(s),true):s;if(preview)state.market=[...s.market];view?.update(state,step===1?0:step===2?1:-1);
 if(step===0){copy.append(btn('Show me the first move →',()=>{step=1;draw()}));let note=document.createElement('small');note.textContent='Guided opening · two players · no timer · no rules to memorise';copy.append(note);}
 if(step===1){copy.append(btn('Recruit the Compute Chokepoint · 1 Favor',recruit));}
 if(step===2){let c=document.createElement('div');c.className='lesson-effect';c.textContent=preview?'PREVIEW · A 3 → 4 · Rules opens · Gate costs 0 Favor':'Three 3s = a tie. No corner is free. Your Frame Plot can change that.';copy.append(c);copy.append(btn(preview?'Play Frame + recruit the Gate · free':'Preview the A die: 3 → 4',()=>{if(!preview){preview=true;draw()}else{s=apply(s,lessonFrame(s));invariant(s);preview=false;step=3;draw()}}));if(preview)copy.append(btn('Undo preview',()=>{preview=false;draw()},'quiet'));let tip=document.createElement('small');tip.textContent='A Frame Plot changes one die by ±1 or swaps two corners, then recruits. This uses your turn and the Plot. The dice are shared—not rolled every turn.';copy.append(tip);}
 if(step===3){let link=document.createElement('div');link.className='lesson-link';link.innerHTML='<strong>COMPUTE</strong><span>Resources →<br>← Rules</span><strong>PEER REVIEW</strong>';copy.append(link);let b=document.createElement('div');b.className='lesson-receipt';b.innerHTML=`<strong>${production(s,0)}</strong> points this turn <span>+ 1 from turn one = ${s.players[0].bank} banked</span>`;copy.append(b,btn('What can I do next? →',()=>{step=4;draw()}));}
 if(step===4){let list=document.createElement('div');list.className='lesson-options';list.innerHTML='<p><b>BUILD</b> Recruit a market card. Match SUPPLIES to NEEDS.</p><p><b>INTERFERE</b> Poach for 1 Favor. Its owner may veto for 2.</p><p><b>PLAY A PLOT</b> Read its effect, then use it when it helps.</p>';copy.append(list,btn(localStorage.getItem('handshake-r08')?'Replace saved game with this opening →':'Continue this game →',()=>{dialog.close();onFinish(s)}),btn('Choose Solo or 2–6 players',()=>{dialog.close();onFinish(null)},'quiet'));let note=document.createElement('small');note.textContent='This was a guided opening: the Committee held position twice. Continue from round 3, or deal a fresh game. Your role can add 2 points at the end. Rules stay available. Skip / return preserves your existing saved game.';copy.append(note);}
 copy.classList.remove('arrive');void copy.offsetWidth;copy.classList.add('arrive');h.tabIndex=-1;h.focus({preventScroll:true});}
 function recruit(){if(step!==1)return;s=prepareFrame(lessonRecruit(s));invariant(s);step=2;draw();}
 return{async open(){s=lessonState(cards);step=0;preview=false;dialog.showModal();draw();if(!view){try{view=await board(stage,i=>{if(step===1&&i===0){view.update(s,0);copy.querySelector('button')?.focus()}});draw()}catch{stage.textContent='Follow the steps at right. All tutorial actions work without 3D.'}}},close(){dialog.close()}};
}
